              "F10"
            ],
            "supported_state": "B余额须排除各期违法利息资本化，并适用合法结息规则及以最初本金计算的整体本息上限；逾期部分另按第28条核对。不能直接采用最后一张借据金额，也不能累加全部纸面本金。",
            "legal_basis": [
              "lending-2020-12:27",
              "lending-2020-12:28"
            ],
            "amount_status": "精确金额待后续逐段计算与复算"
          },
          {
            "id": "N_B_GUARANTEE",
            "depends_on": [
